export const productionSteps=['stimulate','fuse','select','clone','purify'];
export const productionLabels=['Start with the source cells','Stimulated antibody-making lymphocyte','Hybridoma combines both capabilities','Select one suitable hybridoma','Cloned identical antibody-making cells','Collected and purified antibodies'];
export function productionAdvance(step,action){return Number.isInteger(step)&&step>=0&&step<productionSteps.length&&productionSteps[step]===action?step+1:step;}
export function assayResult(condition,step){if(step<3)return'pending';return condition==='present'?'positive':condition==='absent'?'negative':'invalid';}
export function assayBands(condition,step){return{test:step>=2&&condition!=='absent',control:step>=3&&condition!=='invalid'};}
